command:
/**
 * SVA example: Weapon Throw and Return
 * Throws a weapon at every target and brings it back to the thrower's hand, like a returning
 * dagger or a thrown warhammer. Targets are hit one after another.
 *
 * Usage: select the thrower, target one or more tokens, run. Change WEAPON below.
 * Hold SHIFT while clicking the macro to make the throws miss.
 * Requires: Sargas Visual Automation + JB2A (Patreon). No Sequencer needed.
 */
const SVA = game.modules.get("sargas-visual-automation")?.api;
if (!SVA?.ready) return ui.notifications.error("Sargas Visual Automation is not ready.");

const WEAPONS = {
  dagger: {
    go: "jb2a.dagger.throw.01.white",
    back: "jb2a.dagger.return.01.white"
  },
  hammer: { go: "jb2a.hammer.throw", back: "jb2a.hammer.return" }
};
const WEAPON = "dagger"; // "dagger" | "hammer"
// How early the return starts, in ms before the throw ends (more negative = earlier, positive = pause).
const RETURN_OFFSET_MS = -700;

const thrower = canvas.tokens.controlled[0] ?? token;
const targets = [...game.user.targets];
if (!thrower) return ui.notifications.warn("Select the throwing token.");
if (!targets.length) return ui.notifications.warn("Target at least one token.");
const missed = ["ShiftLeft", "ShiftRight"].some((code) => game.keyboard.downKeys.has(code));
const { go, back } = WEAPONS[WEAPON] ?? WEAPONS.dagger;

const seq = SVA.sequence();
for (const target of targets) {
  seq.effect().file(go).atLocation(thrower).stretchTo(target).missed(missed).waitUntilFinished(RETURN_OFFSET_MS);
  // The return file is drawn from the thrower to the target and animates back towards the thrower.
  seq.effect().file(back).atLocation(thrower).stretchTo(target).missed(missed).waitUntilFinished();
}
await seq.play();
